#define BENCH_NCOEFF (BENCH_MAX_DEGREE + 1)
#endif


/* Bounds the source keeps inside its own __CUDACC__ guard;
 * lifted here so every Metal translation unit shares one copy. */
#ifndef TD_GROUP_W
#define TD_GROUP_W 8
#endif
